package pfm.android;

import android.app.*;
import android.content.*;
import java.io.*;
import java.util.*;
import org.json.*;

/** Versioned native career foundation. v1 is an audited, read-only import boundary. */
final class NativeCareerStore {
    static final int SCHEMA=2;
    static class Club {String id,name,league;int sourceId,balance,wageBudget;}
    static class Player {String id,name,owner,nationality;int sourceId,position,age,overall,value,wage,contractWage,contractUntil;}
    static class Career {int schema,slot,season,created;String activeLeague,userClub;ArrayList<Club> clubs=new ArrayList<Club>();ArrayList<Player> players=new ArrayList<Player>();}
    private NativeCareerStore() {}
    private static File file(Context c){return new File(c.getFilesDir(),"native-career-slot-"+NativeWorldCenter.slot()+".json");}
    private static File backup(Context c){return new File(c.getFilesDir(),"native-career-slot-"+NativeWorldCenter.slot()+".backup.json");}
    private static String activeLeague(){try{return String.valueOf(Class.forName("PfmSeasonBridge").getMethod("leagueCode").invoke(null));}catch(Throwable t){return NativeWorldCenter.active();}}
    private static String userClub(){try{return String.valueOf(Class.forName("PfmSeasonBridge").getMethod("teamName").invoke(null));}catch(Throwable t){return "";}}
    private static int legacyBudget(){try{return ((Number)Class.forName("PfmTransferBridge").getMethod("budget").invoke(null)).intValue();}catch(Throwable t){return 0;}}
    private static Career imported(){Career c=new Career();c.schema=SCHEMA;c.slot=NativeWorldCenter.slot();c.season=NativeWorldCenter.season();c.created=(int)(System.currentTimeMillis()/1000L);c.activeLeague=activeLeague();c.userClub=userClub();for(String code:NativeWorldCenter.C){ArrayList<NativeWorldCenter.T> teams=NativeWorldCenter.leagues.get(code);if(teams==null)continue;for(NativeWorldCenter.T t:teams){Club club=new Club();club.id=code+":"+t.id;club.name=t.name;club.league=code;club.sourceId=t.id;c.clubs.add(club);long wages=0,values=0;for(NativeWorldCenter.P p:t.ps){Player x=new Player();x.id=club.id+":"+p.id;x.name=p.name;x.owner=club.id;x.nationality=p.nat.split(" • ")[0];x.sourceId=p.id;x.position=p.pos;x.age=p.age;x.overall=p.ovr;x.value=p.value;x.wage=p.wage;x.contractWage=p.wage;x.contractUntil=c.season+2+Math.abs(x.id.hashCode()%4);wages+=p.wage;values+=p.value;c.players.add(x);}club.wageBudget=(int)Math.min(Integer.MAX_VALUE,Math.max(1000000L,wages*115L/100L));club.balance=(int)Math.min(500000000L,Math.max(2000000L,values/4L));if(code.equals(c.activeLeague)&&t.name.equalsIgnoreCase(c.userClub))club.balance=legacyBudget();}}return c;}
    private static String validate(Career c){if(c.schema!=SCHEMA)return "unsupported schema "+c.schema;if(c.slot!=NativeWorldCenter.slot())return "wrong career slot";HashSet<String> clubs=new HashSet<String>(),players=new HashSet<String>();for(Club x:c.clubs){if(x.id==null||!clubs.add(x.id))return "duplicate club id";if(x.balance<0||x.wageBudget<=0)return "invalid club finance";}for(Player x:c.players){if(x.id==null||!players.add(x.id))return "duplicate player id";if(!clubs.contains(x.owner))return "player without owner";if(x.age<16||x.age>50||x.position<0||x.position>3)return "invalid player data";if(x.contractWage<=0||x.contractUntil<c.season)return "invalid contract";}if(c.clubs.size()!=98||c.players.size()!=2281)return "unexpected import size";return "OK";}
    private static JSONObject json(Career c)throws Exception{JSONObject root=new JSONObject();root.put("schema",c.schema);root.put("slot",c.slot);root.put("season",c.season);root.put("created",c.created);root.put("activeLeague",c.activeLeague);root.put("userClub",c.userClub);JSONArray clubs=new JSONArray();for(Club x:c.clubs){JSONObject o=new JSONObject();o.put("id",x.id);o.put("name",x.name);o.put("league",x.league);o.put("sourceId",x.sourceId);o.put("balance",x.balance);o.put("wageBudget",x.wageBudget);clubs.put(o);}root.put("clubs",clubs);JSONArray players=new JSONArray();for(Player x:c.players){JSONObject o=new JSONObject();o.put("id",x.id);o.put("name",x.name);o.put("owner",x.owner);o.put("nationality",x.nationality);o.put("sourceId",x.sourceId);o.put("position",x.position);o.put("age",x.age);o.put("overall",x.overall);o.put("value",x.value);o.put("wage",x.wage);o.put("contractWage",x.contractWage);o.put("contractUntil",x.contractUntil);players.put(o);}root.put("players",players);return root;}
    private static Career parse(String text)throws Exception{JSONObject root=new JSONObject(text);Career c=new Career();c.schema=root.getInt("schema");c.slot=root.getInt("slot");c.season=root.getInt("season");c.created=root.getInt("created");c.activeLeague=root.optString("activeLeague");c.userClub=root.optString("userClub");JSONArray clubs=root.getJSONArray("clubs");for(int i=0;i<clubs.length();i++){JSONObject o=clubs.getJSONObject(i);Club x=new Club();x.id=o.getString("id");x.name=o.getString("name");x.league=o.getString("league");x.sourceId=o.getInt("sourceId");x.balance=o.optInt("balance",0);x.wageBudget=o.optInt("wageBudget",0);c.clubs.add(x);}JSONArray players=root.getJSONArray("players");for(int i=0;i<players.length();i++){JSONObject o=players.getJSONObject(i);Player x=new Player();x.id=o.getString("id");x.name=o.getString("name");x.owner=o.getString("owner");x.nationality=o.getString("nationality");x.sourceId=o.getInt("sourceId");x.position=o.getInt("position");x.age=o.getInt("age");x.overall=o.getInt("overall");x.value=o.getInt("value");x.wage=o.getInt("wage");x.contractWage=o.optInt("contractWage",0);x.contractUntil=o.optInt("contractUntil",0);c.players.add(x);}return c;}
    private static Career migrate(Career old){if(old.schema==SCHEMA)return old;Career fresh=imported();HashMap<String,Club> fc=new HashMap<String,Club>();for(Club x:fresh.clubs)fc.put(x.id,x);HashMap<String,Player> fp=new HashMap<String,Player>();for(Player x:fresh.players)fp.put(x.id,x);for(Club x:old.clubs){Club n=fc.get(x.id);if(n!=null){x.balance=n.balance;x.wageBudget=n.wageBudget;}}for(Player x:old.players){Player n=fp.get(x.id);if(n!=null){x.contractWage=n.contractWage;x.contractUntil=n.contractUntil;}}old.schema=SCHEMA;return old;}
    private static String read(File f)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),"UTF-8"));StringBuilder b=new StringBuilder();char[] q=new char[8192];int n;while((n=r.read(q))>0)b.append(q,0,n);r.close();return b.toString();}
    private static void writeAtomic(Context c,Career career)throws Exception{File target=file(c),bak=backup(c),tmp=new File(target.getParentFile(),target.getName()+".tmp");FileOutputStream out=new FileOutputStream(tmp);byte[] data=json(career).toString().getBytes("UTF-8");out.write(data);out.flush();out.getFD().sync();out.close();Career check=parse(read(tmp));String audit=validate(check);if(!"OK".equals(audit)){tmp.delete();throw new IOException(audit);}if(target.exists()){if(bak.exists())bak.delete();if(!target.renameTo(bak))throw new IOException("backup rename failed");}if(!tmp.renameTo(target)){if(bak.exists())bak.renameTo(target);throw new IOException("atomic rename failed");}}
    static synchronized Career ensure(Context context)throws Exception{Context c=context.getApplicationContext();File target=file(c);if(target.exists()){try{Career old=parse(read(target));if(old.schema<SCHEMA){old=migrate(old);writeAtomic(c,old);}if("OK".equals(validate(old)))return old;}catch(Throwable ignored){}}File bak=backup(c);if(bak.exists()){try{Career old=migrate(parse(read(bak)));if("OK".equals(validate(old))){writeAtomic(c,old);return old;}}catch(Throwable ignored){}}Career fresh=imported();String audit=validate(fresh);if(!"OK".equals(audit))throw new IOException(audit);writeAtomic(c,fresh);return fresh;}
    static void show(Activity a){try{Career c=ensure(a);String audit=validate(c);File f=file(a);Club user=null;long payroll=0;for(Club x:c.clubs)if(x.league.equals(c.activeLeague)&&x.name.equalsIgnoreCase(c.userClub))user=x;for(Player x:c.players)if(user!=null&&x.owner.equals(user.id))payroll+=x.contractWage;String finance=user==null?"unavailable":"£"+(user.balance/1000000.0)+"m; payroll £"+(payroll/1000000.0)+"m / £"+(user.wageBudget/1000000.0)+"m";String body="Schema: "+c.schema+"\nCareer slot: "+c.slot+"\nSeason source: "+c.season+"\nActive league: "+c.activeLeague+"\nUser club: "+c.userClub+"\nClubs: "+c.clubs.size()+"\nPlayers: "+c.players.size()+"\nContracts: "+c.players.size()+"\nClub finance: "+finance+"\nOwnership + contract audit: "+audit+"\nSnapshot: "+f.getName()+" ("+(f.length()/1024)+" KB)\nBackup policy: atomic previous-version copy\n\nSchema v1 is migrated automatically and retained as the backup. The legacy save remains untouched.";new AlertDialog.Builder(a).setTitle("Native career data").setMessage(body).setPositiveButton("Close",null).show();}catch(Throwable t){new AlertDialog.Builder(a).setTitle("Native career data error").setMessage(String.valueOf(t.getMessage())).setPositiveButton("Close",null).show();}}
}
